    background: #243447; padding: 7px 14px; font-size: 12px; color: #8ba4b8;
    font-family: 'JetBrains Mono', monospace; border-bottom: 1px solid #2d4052;
}
pre code {
    display: block; padding: 16px 20px;
    font-family: 'JetBrains Mono', 'Consolas', monospace;
    font-size: 13px; line-height: 1.6; color: #e2e8f0; overflow-x: auto;
}
pre code .kw { color: #c792ea; }
pre code .str { color: #c3e88d; }
pre code .cmt { color: #546e7a; font-style: italic; }
pre code .num { color: #f78c6c; }
pre code .func { color: #82aaff; }

table {
    width: 100%; border-collapse: separate; border-spacing: 0;
