    font-size: 13px; font-weight: 600; text-align: center; min-width: 90px; line-height: 1.4;
}
.arch-node.primary { background: var(--bg-green-50); border: 2px solid var(--primary); color: var(--primary-dark); }
.arch-node.secondary { background: #fff7ed; border: 2px solid #f59e0b; color: #b45309; }
.arch-node.accent { background: #eff6ff; border: 2px solid #3b82f6; color: #1e40af; }
.arch-connector { color: var(--text-muted); font-size: 20px; font-weight: 700; flex-shrink: 0; }

.scenario-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin: 20px 0; }
.scenario-card { padding: 16px 18px; border-radius: var(--radius-md); border-left: 4px solid; }
.scenario-card h4 { margin-top: 0; font-size: 14px; padding-bottom: 4px; border-bottom: none; }
.scenario-card ul { margin: 6px 0 0 0; padding-left: 16px; }
.scenario-card li { font-size: 13px; color: var(--text-secondary); margin-bottom: 4px; line-height: 1.5; }
.scenario-card.blue { border-color: #3b82f6; background: #eff6ff; }
.scenario-card.blue h4 { color: #1e40af; }
.scenario-card.green { border-color: var(--primary); background: var(--bg-green-50); }
.scenario-card.green h4 { color: var(--primary-dark); }
.scenario-card.purple { border-color: #8b5cf6; background: #f5f3ff; }
.scenario-card.purple h4 { color: #6d28d9; }
.scenario-card.orange { border-color: #f59e0b; background: #fffbeb; }
.scenario-card.orange h4 { color: #b45309; }

.practice-box {
    background: linear-gradient(135deg, var(--bg-teal-50) 0%, var(--bg-green-50) 100%);
    border: 1px solid rgba(77,184,164,0.25);
    border-left: 4px solid var(--primary);
    border-radius: 0 var(--radius-md) var(--radius-md) 0;
    padding: 20px 22px; margin: 24px 0;
}
.practice-box::before {
    content: '\1F527  动手试一试'; display: block; font-weight: 700;
    color: var(--primary-dark); font-size: 15px; margin-bottom: 10px;
    padding-bottom: 8px; border-bottom: 1px dashed rgba(77,184,164,0.25);
}
.practice-box h4 { display: none; }
.practice-box ol, .practice-box ul { margin: 8px 0 0 0; padding-left: 20px; }
.practice-box li { color: var(--text-secondary); margin-bottom: 6px; line-height: 1.7; }
.practice-box p { color: var(--text-secondary); margin-bottom: 8px; }
.practice-box code {
    background: rgba(77,184,164,0.1); padding: 1px 6px; border-radius: 3px;
    font-family: 'JetBrains Mono', monospace; font-size: 13px; color: var(--primary-dark);
}

.self-check {
    background: #fefce8; border: 1px solid rgba(245,158,11,0.2);
    border-left: 4px solid #f59e0b;
    border-radius: 0 var(--radius-md) var(--radius-md) 0;
    padding: 20px 22px; margin: 24px 0;
}
.self-check::before {
    content: '\2753  检验你的理解'; display: block; font-weight: 700;
    color: #b45309; font-size: 15px; margin-bottom: 10px;
    padding-bottom: 8px; border-bottom: 1px dashed rgba(245,158,11,0.3);
}
.self-check h4 { display: none; }
.self-check ol { margin: 8px 0 0 0; padding-left: 20px; counter-reset: check-counter; list-style: none; }
.self-check ol li { counter-increment: check-counter; position: relative; padding-left: 8px; color: var(--text-secondary); margin-bottom: 10px; line-height: 1.7; }
.self-check ol li::before { content: 'Q' counter(check-counter); position: absolute; left: -20px; color: #d97706; font-weight: 700; font-size: 13px; }
.self-check p { color: var(--text-secondary); margin-bottom: 6px; }
.self-check .check-answer { color: var(--text-muted); font-size: 13px; font-style: italic; margin-top: 4px; }

.editor-note {
    background: linear-gradient(135deg, #eff6ff, #f0f7ff);
    border: 1px solid rgba(59,130,246,0.15);
    border-left: 3px solid #3b82f6;
    border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
    padding: 12px 16px; margin: 18px 0; font-size: 14px; color: #1e40af; line-height: 1.7;
}
.editor-note::before {
    content: '\1f4d6  编者提示'; display: inline-block; font-weight: 700;
    font-size: 11px; letter-spacing: 1.5px; margin-right: 8px;
    padding: 1px 7px; background: rgba(59,130,246,0.1); border-radius: 3px; color: #2563eb;
}

.difficulty-tag { display: inline-block; padding: 2px 10px; border-radius: 12px; font-size: 13px; font-weight: 600; letter-spacing: 0.5px; }
.diff-beginner { background: #dcfce7; color: #15803d; }
.diff-intermediate { background: #fef3c7; color: #b45309; }
.diff-advanced { background: #fee2e2; color: #dc2626; }

.chapter-nav {
    display: flex; justify-content: center; align-items: center; gap: 12px;
    margin-top: 40px; padding: 0 20px;
}
.chapter-nav a {
    display: inline-flex; align-items: center; gap: 6px;
    padding: 10px 24px; border-radius: var(--radius-md);
    font-size: 14px; font-weight: 600; text-decoration: none;
    transition: all 0.2s ease; cursor: pointer;
}
.chapter-nav .nav-prev,
.chapter-nav .nav-next {
    background: var(--bg-white); color: var(--primary);
    border: 1px solid rgba(77,184,164,0.25);
}
.chapter-nav .nav-prev:hover,
.chapter-nav .nav-next:hover {
    background: var(--bg-green-50); border-color: var(--primary);
    box-shadow: 0 2px 8px rgba(77,184,164,0.12);
}
.chapter-nav .nav-catalog {
    background: var(--gradient-main); color: #fff; border: none;
}
.chapter-nav .nav-catalog:hover {
    opacity: 0.9; box-shadow: 0 2px 8px rgba(77,184,164,0.25);
}
.chapter-nav .nav-placeholder {
    width: 120px;
}

.page-footer {
    text-align: center; padding: 28px 0 16px 0; color: var(--text-muted);
    font-size: 12px; letter-spacing: 1px;
    border-top: 1px solid var(--border-light); margin-top: 24px;
}

@import url('https://fonts.loli.net/css2?family=Noto+Sans+SC:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap');

:root {
    --primary: #4db8a4;
    --primary-dark: #3a9e8c;
    --primary-light: #6fcfbe;
    --accent: #45a899;
    --accent-light: #a8e6db;
    --gradient-main: linear-gradient(135deg, #4db8a4, #5ec6b4);
    --gradient-soft: linear-gradient(135deg, #4db8a4 0%, #5ec6b4 50%, #7dd4c6 100%);
    --gradient-header: linear-gradient(135deg, #4db8a4, #62c9b8, #7dd4c6);
    --gradient-header-dark: linear-gradient(135deg, #2a7d6e, #358f7f, #4db8a4);
    --bg-page: #f6f8fa;
    --bg-white: #ffffff;
    --bg-gray-50: #f8f9fb;
    --bg-gray-100: #f0f2f5;
    --bg-green-50: #edf9f5;
    --bg-teal-50: #f0faf7;
    --text-primary: #1f2937;
    --text-secondary: #4b5563;
    --text-muted: #9ca3af;
    --border-light: #e5e7eb;
    --border-default: #d1d5db;
    --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
    --shadow-card: 0 1px 3px rgba(0,0,0,0.05), 0 1px 2px rgba(0,0,0,0.03);
    --shadow-card-hover: 0 4px 12px rgba(77,184,164,0.12), 0 2px 4px rgba(0,0,0,0.04);
    --radius-sm: 6px;
    --radius-md: 10px;
    --radius-lg: 12px;
    --radius-xl: 16px;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
    background: var(--bg-page);
    color: var(--text-primary);
    font-family: 'Noto Sans SC', -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", 'Segoe UI', sans-serif;
    line-height: 1.8;
    font-size: 15px;
    -webkit-font-smoothing: antialiased;
}

.chapter-container { max-width: 880px; margin: 0 auto; padding: 48px 40px; background: var(--bg-white); }

.chapter-header {
    background: var(--gradient-header); border-radius: var(--radius-lg);
    padding: 28px 32px; margin-bottom: 32px; position: relative; overflow: hidden;
}
.chapter-header::before {
    content: ''; position: absolute; top: -60%; right: -15%;
    width: 220px; height: 220px;
    background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 70%);
    border-radius: 50%;
}
.chapter-header h2 { color: #fff; font-size: 22px; font-weight: 700; letter-spacing: 0.5px; position: relative; z-index: 1; }

.chapter-guide {
    background: var(--bg-white); border: 1px solid var(--border-light);
    border-radius: var(--radius-lg); overflow: hidden;
    margin-bottom: 28px; box-shadow: var(--shadow-card);
}
.guide-meta {
    display: flex; align-items: center; flex-wrap: wrap;
    background: var(--bg-gray-50); border-bottom: 1px solid var(--border-light); padding: 0;
}
.guide-meta-item {
    display: flex; align-items: center; gap: 6px;
    padding: 11px 18px; font-size: 13px; color: var(--text-secondary);
    border-right: 1px solid var(--border-light); white-space: nowrap; line-height: 1;
}
.guide-meta-item:last-child { border-right: none; }
.guide-meta-item .meta-icon { font-size: 14px; flex-shrink: 0; }
.guide-body { padding: 18px 24px 20px; }
.guide-learn { margin-bottom: 14px; }
.guide-learn-label {
    font-size: 13px; font-weight: 700; color: var(--primary);
    letter-spacing: 1.5px; margin-bottom: 8px; display: block;
}
.guide-learn-label::before {
    content: ''; display: inline-block; width: 7px; height: 7px;
    border-radius: 50%; background: var(--primary); margin-right: 8px; vertical-align: middle;
}
.guide-learn ul { list-style: none; padding: 0; margin: 0; display: flex; flex-wrap: wrap; gap: 4px 24px; }
.guide-learn li { font-size: 14px; color: var(--text-secondary); line-height: 1.7; padding-left: 16px; position: relative; }
.guide-learn li::before { content: '▸'; position: absolute; left: 0; color: var(--accent-light); font-weight: 700; font-size: 14px; }
.guide-concepts { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; }
.guide-concepts-label {
    font-size: 13px; font-weight: 700; color: var(--primary);
    letter-spacing: 1.5px; margin-right: 4px;
}
.guide-concepts-label::before {
    content: ''; display: inline-block; width: 7px; height: 7px;
    border-radius: 50%; background: var(--primary); margin-right: 8px; vertical-align: middle;
}
.guide-concept-tag {
    display: inline-block; background: var(--bg-green-50);
    border: 1px solid rgba(77,184,164,0.2);
    color: var(--primary-dark); padding: 3px 12px; border-radius: 14px;
    font-size: 13px; font-weight: 500;
}

.chapter-content { padding: 0; }
.chapter-content h3 {
    color: var(--text-primary); font-size: 17px; font-weight: 700;
    margin: 32px 0 14px 0; padding: 10px 16px;
    background: var(--bg-green-50); border-left: 3px solid var(--primary);
    border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
}
.chapter-content h4 {
    color: var(--text-primary); font-size: 15px; font-weight: 600;
    margin: 22px 0 10px 0; padding-bottom: 6px; border-bottom: 1px solid var(--border-light);
}
.chapter-content p { color: var(--text-secondary); line-height: 1.85; margin-bottom: 14px; text-align: justify; }
.chapter-content ul, .chapter-content ol { margin: 12px 0 16px 0; padding-left: 22px; color: var(--text-secondary); }
.chapter-content li { margin-bottom: 6px; line-height: 1.7; padding-left: 4px; }
.chapter-content li::marker { color: var(--primary); font-weight: 600; }

.concept-block {
    background: var(--bg-green-50); border: 1px solid rgba(77,184,164,0.15);
    border-radius: var(--radius-md); padding: 18px 22px; margin: 18px 0;
}
.concept-block h4 { color: var(--primary-dark); border-bottom: none; margin-top: 0; padding-bottom: 4px; }
.key-point {
