.tip-box.important { border-left-color: #ef4444; background: #fef2f2; }
.tip-box.important::before { content: 'IMPORTANT'; color: #dc2626; background: #fee2e2; }

pre {
    background: #1a2332; border-radius: var(--radius-md); margin: 18px 0;
    overflow: hidden; border: 1px solid #243447;
}
pre .code-header {
    background: #243447; padding: 7px 14px; font-size: 12px; color: #8ba4b8;
    font-family: 'JetBrains Mono', monospace; border-bottom: 1px solid #2d4052;
}
pre code {
    display: block; padding: 16px 20px;
    font-family: 'JetBrains Mono', 'Consolas', monospace;
    font-size: 13px; line-height: 1.6; color: #e2e8f0; overflow-x: auto;
}
pre code .kw { color: #c792ea; }
pre code .str { color: #c3e88d; }
pre code .cmt { color: #546e7a; font-style: italic; }
pre code .num { color: #f78c6c; }
pre code .func { color: #82aaff; }

table {
    width: 100%; border-collapse: separate; border-spacing: 0;
    margin: 20px 0; border-radius: var(--radius-md); overflow: hidden;
    border: 1px solid var(--border-light); font-size: 14px;
}
thead th {
    background: var(--gradient-header); color: #fff; font-weight: 600;
    padding: 11px 16px; text-align: left; font-size: 13px;
}
tbody td { padding: 10px 16px; border-bottom: 1px solid var(--border-light); color: var(--text-secondary); line-height: 1.5; }
tbody tr:nth-child(odd) { background: var(--bg-white); }
tbody tr:nth-child(even) { background: var(--bg-gray-50); }
tbody tr:hover { background: var(--bg-green-50); }
tbody tr:last-child td { border-bottom: none; }

